import React, { useState } from 'react';
import ResetPasswordModal from './ResetPasswordModal';
import axios from 'axios';

export default function StudentDashboard({ userName, userId, handleLogout }) {
  const [showResetModal, setShowResetModal] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // Profile State
  const [isEditing, setIsEditing] = useState(false);
  const [profile, setProfile] = useState({ 
      name: userName, // 🟢 මෙතනට ලොග් වෙන කෙනාගේ නම එනවා
      grade: 'Grade 10', 
      phone: '0712345678', 
      address: 'Colombo, Sri Lanka' 
  });

  const handleProfileUpdate = () => {
      // ඩේටාබේස් එකට යවන කෝඩ් එක මෙතනට එනවා (දැනට UI එක පෙන්නන්න හදලා තියෙන්නේ)
      alert("✅ Profile details updated successfully!");
      setIsEditing(false);
  };

  // 🟢 ටැබ් මාරු වෙද්දී අදාළ කොටස පෙන්වන ප්‍රධාන Function එක
  const renderContent = () => {
    switch (activeTab) {
      
      // 1. DASHBOARD TAB
      case 'dashboard':
        return (
          <>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px', boxShadow: '0 10px 25px rgba(21,128,61,0.2)' }}>
              <h1 style={{ margin: '0 0 10px 0', fontSize: '32px' }}>Welcome back, {profile.name}! 👋</h1>
              <p style={{ margin: 0, opacity: 0.9, fontSize: '16px' }}>Ready to continue your learning journey today? Check your pending quizzes and new materials.</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '40px' }}>
              <DashboardCard title="Enrolled Courses" count="01" icon="🎓" color="#eff6ff" textColor="#1d4ed8" />
              <DashboardCard title="Total Subjects" count="04" icon="📚" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Pending Quizzes" count="02" icon="⏳" color="#fef2f2" textColor="#b91c1c" />
              <DashboardCard title="Completed" count="12" icon="✅" color="#fefce8" textColor="#a16207" />
            </div>
          </>
        );

      // 2. MY SUBJECTS TAB
      case 'subjects':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📚 My Enrolled Subjects</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
                <SubjectCard subject="Science" teacher="Mr. Ravindu Jayaweera" progress="75%" />
                <SubjectCard subject="Mathematics" teacher="Mr. Charaka Dikwella" progress="60%" />
                <SubjectCard subject="English" teacher="Mrs. Amal Perera" progress="90%" />
            </div>
          </div>
        );

      // 3. ONLINE QUIZZES TAB
      case 'quizzes':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📝 Online Quizzes</h2>
            <div style={{ backgroundColor: 'white', borderRadius: '12px', padding: '20px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
                <QuizItem title="Science Term Test 1" time="30 Mins" questions="25" status="Pending" color="#ef4444" />
                <QuizItem title="Maths Weekly Revision" time="15 Mins" questions="10" status="Completed" color="#10b981" />
            </div>
          </div>
        );

      // 4. MY PROFILE TAB
      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', maxWidth: '600px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px', borderBottom: '2px solid #f1f5f9', paddingBottom: '15px' }}>
                <h2 style={{ color: '#15803d', margin: 0 }}>👤 Personal Information</h2>
                {!isEditing ? (
                    <button onClick={() => setIsEditing(true)} style={editBtnStyle}>Edit Profile</button>
                ) : (
                    <button onClick={handleProfileUpdate} style={saveBtnStyle}>Save Changes</button>
                )}
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              <div>
                  <label style={labelStyle}>Full Name</label>
                  <input type="text" value={profile.name} onChange={(e) => setProfile({...profile, name: e.target.value})} disabled={!isEditing} style={inputStyle(isEditing)} />
              </div>
              <div style={{ display: 'flex', gap: '20px' }}>
                  <div style={{ flex: 1 }}>
                      <label style={labelStyle}>Grade</label>
                      <input type="text" value={profile.grade} disabled style={inputStyle(false)} />
                  </div>
                  <div style={{ flex: 1 }}>
                      <label style={labelStyle}>Phone Number</label>
                      <input type="text" value={profile.phone} onChange={(e) => setProfile({...profile, phone: e.target.value})} disabled={!isEditing} style={inputStyle(isEditing)} />
                  </div>
              </div>
              <div>
                  <label style={labelStyle}>Residence Address</label>
                  <input type="text" value={profile.address} onChange={(e) => setProfile({...profile, address: e.target.value})} disabled={!isEditing} style={inputStyle(isEditing)} />
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f4f7f6', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 SIDEBAR */}
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '25px 0', display: 'flex', flexDirection: 'column', boxShadow: '4px 0 15px rgba(0,0,0,0.1)', zIndex: 10 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
          <h2 style={{ margin: 0, fontSize: '24px', letterSpacing: '1px' }}>LMS PORTAL</h2>
          <p style={{ margin: '5px 0 0 0', fontSize: '12px', color: '#bbf7d0' }}>Student Dashboard</p>
        </div>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'subjects'} onClick={() => setActiveTab('subjects')} icon="📚" text="My Subjects" />
          <SidebarBtn active={activeTab === 'quizzes'} onClick={() => setActiveTab('quizzes')} icon="📝" text="Online Quizzes" />
          <div style={{ height: '1px', backgroundColor: 'rgba(255,255,255,0.1)', margin: '15px 0' }}></div>
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile" />
          <SidebarBtn active={false} onClick={() => setShowResetModal(true)} icon="🔑" text="Change Password" />
        </div>

        <div style={{ marginTop: 'auto', padding: '0 15px' }}>
          <button onClick={handleLogout} style={{ width: '100%', padding: '14px', backgroundColor: 'rgba(239, 68, 68, 0.1)', color: '#fca5a5', border: '1px solid rgba(239, 68, 68, 0.3)', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', transition: '0.3s' }} onMouseOver={(e) => e.target.style.backgroundColor = '#ef4444'} onMouseOut={(e) => e.target.style.backgroundColor = 'rgba(239, 68, 68, 0.1)'}>
            🚪 Logout
          </button>
        </div>
      </div>

      {/* 🟢 MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {renderContent()}
      </div>

      {showResetModal && <ResetPasswordModal userName={userName} role="student" setShowResetModal={setShowResetModal} />}
    </div>
  );
}

// 🟢 Custom UI Components 
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '12px', fontWeight: active ? 'bold' : 'normal', transition: 'all 0.2s ease' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, color, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}>
    <div>
        <p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '14px', fontWeight: 'bold' }}>{title}</p>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '32px' }}>{count}</h2>
    </div>
    <div style={{ width: '60px', height: '60px', borderRadius: '50%', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '28px' }}>
        {icon}
    </div>
  </div>
);

const SubjectCard = ({ subject, teacher, progress }) => (
    <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', border: '1px solid #f1f5f9' }}>
        <h3 style={{ margin: '0 0 5px 0', color: '#1e293b' }}>{subject}</h3>
        <p style={{ margin: '0 0 20px 0', color: '#64748b', fontSize: '14px' }}>Lecturer: {teacher}</p>
        <div style={{ backgroundColor: '#e2e8f0', height: '8px', borderRadius: '4px', overflow: 'hidden', marginBottom: '15px' }}>
            <div style={{ width: progress, height: '100%', backgroundColor: '#15803d' }}></div>
        </div>
        <button style={{ width: '100%', padding: '10px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Access Materials</button>
    </div>
);

const QuizItem = ({ title, time, questions, status, color }) => (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px', borderBottom: '1px solid #f1f5f9' }}>
        <div>
            <h4 style={{ margin: '0 0 5px 0', color: '#1e293b' }}>{title}</h4>
            <p style={{ margin: 0, color: '#64748b', fontSize: '13px' }}>{questions} Questions • {time}</p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
            <span style={{ backgroundColor: `${color}20`, color: color, padding: '5px 12px', borderRadius: '20px', fontSize: '12px', fontWeight: 'bold' }}>{status}</span>
            <button style={{ padding: '8px 15px', backgroundColor: color, color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>{status === 'Pending' ? 'Start Quiz' : 'View Results'}</button>
        </div>
    </div>
);

// Styles
const labelStyle = { display: 'block', marginBottom: '8px', color: '#475569', fontSize: '14px', fontWeight: 'bold' };
const inputStyle = (isEditing) => ({ width: '100%', padding: '12px', borderRadius: '8px', border: isEditing ? '1px solid #3b82f6' : '1px solid #cbd5e1', backgroundColor: isEditing ? 'white' : '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b' });
const editBtnStyle = { padding: '8px 16px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' };
const saveBtnStyle = { padding: '8px 16px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' };
